mapper.select:
SELECT p.NO AS `no`, p.ORI_NO AS ori_no, p.OWNER_ID AS owner_id, p.ORI_OWNER_ID AS ori_owner_id, p.`YEAR` AS `year`, p.`MONTH` AS `month`, p.`DATE` AS `date`, p.TITLE AS title, p.BODY AS body, p.IMG_NAME AS img_name, TIME_FORMAT(p.START_TIME, '%H:%i') AS start_time, DATE_FORMAT(p.REG_DATE, '%Y-%m-%d %H:%i:%s') AS reg_date, DATE_FORMAT(p.MOD_DATE, '%Y-%m-%d %H:%i:%s') AS mod_date FROM PLAN p
p.OWNER_ID = #{ownerId}
AND (p.TITLE LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR p.BODY LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!')
ORDER BY p.`YEAR` DESC, p.`MONTH` DESC, p.`DATE` DESC, (p.START_TIME IS NULL) ASC, p.START_TIME ASC, p.NO DESC LIMIT #{limit}
